import Foundation

/// Test-only access to the protocol vectors copied from orch-relay (see PROVENANCE.md next to this file).
public enum Vectors {
    public static var url: URL { Bundle.module.url(forResource: "vectors_v2", withExtension: "json")! }
    public static var data: Data { try! Data(contentsOf: url) }
}

/// LOCAL Q10 vectors (`wk_commit`, the relay's sequence rules, the device's snapshot rules), generated by orch-mobile from the
/// decision text (scripts/gen-local-g2b-vectors.py). TODO(G2b): replace with orch-relay's `member_lists` / `member_list_snapshots`
/// once G2b publishes them (see PROVENANCE.md).
public enum LocalG2bVectors {
    public static var url: URL { Bundle.module.url(forResource: "local_g2b_vectors", withExtension: "json")! }
    public static var data: Data { try! Data(contentsOf: url) }
}
